// Type definitions for frappe-charts
// Project: https://github.com/frappe/charts.git
// Definitions: https://github.com/DefinitelyTyped/DefinitelyTyped
// TypeScript Version: 3.9


declare namespace Frappe {

    type ChartType = "line" | "bar" | "axis-mixed" | "pie" | "percentage" | "heatmap";
    type AxisMode = "span" | "tick";

    interface ChartData {
        labels?: Array<string>;
        datasets?: Array<{
            name?: string;
            type?: ChartType;
            values: Array<number>;
        }>;
        dataPoints?: {
            [x: string]: number;
        };
        start?: Date;
        end?: Date;
    }

    interface SelectEvent {
        label: string;
        values: number[];
        index: number;
    }

    interface TooltipOptions {
        formatTooltipX?: (value: number) => any;
        formatTooltipY?: (value: number) => any;
    }

    export interface Options {
        animate?: 0 | 1;
        title?: string;
        type?: ChartType;
        data: ChartData;
        height?: number;
        colors?: Array<string>;
        axisOptions?: {
            xAxisMode?: AxisMode;
            yAxisMode?: AxisMode;
            xIsSeries?: 0 | 1;
        }

        barOptions?: {
            spaceRatio?: number;
            stacked?: 0 | 1;
            height?: number;
            depth?: number;
        }

        lineOptions?: {
            dotSize?: number;
            hideLine?: 0 | 1;
            hideDots?: 0 | 1;
            heatline?: 0 | 1;
            regionFill?: number;
            areaFill?: number;
            spline?: 0 | 1;
        }

        isNavigable?: boolean;
        maxSlices?: number;
        truncateLegends?: 0 | 1;
        discreteDomains?: 0 | 1;
        tooltipOptions?: TooltipOptions;
        onDataSelect?: (event: SelectEvent) => void;
        valuesOverPoints?: 0 | 1;
    }

    export class Chart {
        constructor(name: HTMLElement, options: Options);
    }
}
